{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Pentazocine, a phenolic benzomorphan opioid closely related to the query's morphinan scaffold, had a mean absolute oral bioavailability of 18% in healthy subjects, below the 20% threshold, indicating that phenolic opioid first-pass metabolism limits F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Meptazinol, another phenolic opioid analgesic, showed absolute oral bioavailability of only 8.7% in healthy young volunteers, reinforcing that phenolic tertiary-amine opioids with extensive first-pass conjugation tend to fall below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Pethidine, an opioid analgesic, had an absolute oral bioavailability of 48% in healthy volunteers, showing that opioid class alone does not dictate low F; however, pethidine lacks the phenolic morphinan features that drive the query's first-pass metabolism.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C49"],
      "claim": "Paliperidone ER had an absolute oral bioavailability of 28%, above the threshold, but it is a non-phenolic benzisoxazole antipsychotic with different metabolic clearance, limiting transfer to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "ACT-1004-1239, which shares the N-cyclopropylmethyl group, achieved 53% absolute bioavailability, but its non-opioid scaffold and lack of phenolic conjugation make this high-F evidence less decisive for the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest structural and pharmacological analogues—phenolic opioids pentazocine and meptazinol—show absolute oral bioavailability below 20% in healthy subjects, consistent with the query's phenolic morphinan scaffold and extensive first-pass metabolism. High-F evidence from non-phenolic or structurally distant drugs is less transferable despite high retrieval scores. Therefore predict low.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement for the query molecule itself; healthy-subject data for the closest analogues are limited; cirrhosis data show higher F due to reduced first-pass, so healthy F may be lower."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

